// Example of a common NIO leak: forgetting to close a FileChannel
// or failing to release a DirectByteBuffer in a custom pool.
try (FileChannel channel = FileChannel.open(path, StandardOpenOption.READ)) {
    ByteBuffer buffer = ByteBuffer.allocateDirect(1024 * 1024);
    channel.read(buffer);
    // If the buffer is not explicitly managed or the channel is not closed,
    // the native memory remains allocated until the GC cleans up the wrapper.
} catch (IOException e) {
    logger.error("Failed to process NIO stream", e);
}
